liquid:
{% assign safety_margin_seconds = 30 %}
{% assign token_lifetime_seconds = 300 %}
{% assign cache_context = 'dummyjson-demo-products-v1' %}
{% assign token = '' %}
{% assign products_ready = false %}
{% assign error_code = 'CACHE_UNAVAILABLE' %}
{% assign error_message = 'Unable to prepare authentication. Please try again.' %}
{% call {"requestId": "jwt-cache-read"} as cache_response %}
{% assign has_status = cache_response | has_key: 'status' %}
{% assign has_data = cache_response | has_key: 'data' %}
{% assign cache_read_ok = false %}
{% if has_status and has_data %}
  {% if cache_response.status == 200 %}
    {% assign cache_read_ok = true %}
    {% assign has_cache = cache_response.data | has_key: 'jwt-cache-dummyjson' %}
    {% if has_cache %}
      {% assign cache = cache_response.data['jwt-cache-dummyjson'] %}
      {% assign has_token = cache | has_key: 'accessToken' %}
      {% assign has_issued_at = cache | has_key: 'issuedAt' %}
      {% assign has_expiry = cache | has_key: 'expiresAt' %}
      {% assign has_context = cache | has_key: 'context' %}
      {% if has_token and has_issued_at and has_expiry and has_context %}
        {% assign token_valid = cache.accessToken | is_type: 'string' %}
        {% assign issued_at_valid = cache.issuedAt | is_type: 'integer' %}
        {% assign expiry_valid = cache.expiresAt | is_type: 'integer' %}
        {% if token_valid and issued_at_valid and expiry_valid %}
          {% assign now_seconds = 'now' | date: '%s' | plus: 0 %}
          {% assign reuse_until = cache.expiresAt | minus: safety_margin_seconds %}
          {% assign lifetime = cache.expiresAt | minus: cache.issuedAt %}
          {% assign trimmed_token = cache.accessToken | strip %}
          {% if cache.context == cache_context and lifetime == token_lifetime_seconds and cache.issuedAt <= now_seconds and reuse_until > now_seconds and trimmed_token != '' %}
            {% assign token = cache.accessToken %}
          {% endif %}
        {% endif %}
      {% endif %}
    {% endif %}
  {% endif %}
{% endif %}
{% if cache_read_ok %}
  {% for attempt in (1..2) %}
    {% if token == '' %}
      {% assign error_code = 'AUTHENTICATION_FAILED' %}
      {% assign error_message = 'Unable to authenticate with the product service.' %}
      {% assign issued_at = 'now' | date: '%s' | plus: 0 %}
      {% call {"requestId": "jwt-cache-authenticate"} as authentication %}
      {% assign has_status = authentication | has_key: 'status' %}
      {% assign has_data = authentication | has_key: 'data' %}
      {% if has_status and has_data %}
        {% if authentication.status == 200 %}
          {% assign has_token = authentication.data | has_key: 'accessToken' %}
          {% if has_token %}
            {% assign token_is_string = authentication.data.accessToken | is_type: 'string' %}
            {% if token_is_string %}
              {% assign token = authentication.data.accessToken | strip %}
            {% endif %}
          {% endif %}
        {% endif %}
      {% endif %}
      {% if token == '' %}{% break %}{% endif %}
      {% assign expires_at = issued_at | plus: token_lifetime_seconds %}
      {% call {
        "requestId": "jwt-cache-write",
        "systemParamsEmbedded": {"arguments": [{
          "handle": "jwt-cache-dummyjson", "sensitive": true,
          "value": {"accessToken": {{ token | json }}, "issuedAt": {{ issued_at | json }}, "expiresAt": {{ expires_at | json }}, "context": {{ cache_context | json }}}
        }]}
      } as cache_write %}
      {% assign error_code = 'CACHE_UNAVAILABLE' %}
      {% assign error_message = 'Unable to prepare authentication. Please try again.' %}
      {% assign has_status = cache_write | has_key: 'status' %}
      {% unless has_status %}{% break %}{% endunless %}
      {% if cache_write.status != 200 %}{% break %}{% endif %}
    {% endif %}
    {% assign error_code = 'PRODUCTS_UNAVAILABLE' %}
    {% assign error_message = 'Unable to load products. Please try again.' %}
    {% assign authorization = 'Bearer ' | append: token %}
    {% call {
      "requestId": "jwt-cache-products",
      "headersEmbedded": {"Authorization": {{ authorization | json }}}
    } as product_response %}
    {% assign has_status = product_response | has_key: 'status' %}
    {% unless has_status %}{% break %}{% endunless %}
    {% if product_response.status == 401 %}
      {% call {"requestId": "jwt-cache-write"} as cache_clear %}
      {% assign has_status = cache_clear | has_key: 'status' %}
      {% unless has_status %}{% break %}{% endunless %}
      {% if cache_clear.status != 200 %}
        {% assign error_code = 'CACHE_UNAVAILABLE' %}
        {% assign error_message = 'Unable to prepare authentication. Please try again.' %}
        {% break %}
      {% endif %}
      {% assign token = '' %}
      {% continue %}
    {% endif %}
    {% assign has_data = product_response | has_key: 'data' %}
    {% if product_response.status == 200 and has_data %}
      {% assign has_products = product_response.data | has_key: 'products' %}
      {% if has_products %}
        {% assign products_ready = product_response.data.products | is_type: 'array' %}
      {% endif %}
    {% endif %}
    {% break %}
  {% endfor %}
{% endif %}
  {% if products_ready %}
    {% capture product_json %}
    [
      {% for product in product_response.data.products limit: 3 %}
        {% assign has_id = product | has_key: 'id' %}
        {% assign has_title = product | has_key: 'title' %}
        {% assign has_price = product | has_key: 'price' %}
        {% if has_id and has_title and has_price %}
          {% assign id_valid = product.id | is_type: 'integer' %}
          {% assign title_valid = product.title | is_type: 'string' %}
          {% assign price_valid = product.price | is_type: 'number' %}
          {% if id_valid and title_valid and price_valid %}
            {% unless forloop.first %},{% endunless %}
            {"id": {{ product.id | json }}, "title": {{ product.title | json }}, "price": {{ product.price | json }}}
          {% else %}
            {% assign products_ready = false %}
          {% endif %}
        {% else %}
          {% assign products_ready = false %}
        {% endif %}
      {% endfor %}
    ]
    {% endcapture %}
  {% endif %}
{% if products_ready %}
{"ok": true, "products": {{ product_json }}}
{% else %}
{"ok": false, "code": {{ error_code | json }}, "message": {{ error_message | json }}}
{% endif %}
